edits.after:
/* World form rows are not inside the shared property-section container; explicitly stack their labels. */
.form-grid :deep(.ui-property-row){grid-template-columns:minmax(0,1fr);align-items:start;row-gap:var(--ui-label-control-gap)}
.form-grid :deep(.ui-property-control>div:has(>input)){display:flex;flex-wrap:wrap;gap:var(--ui-control-gap);width:100%;min-width:0;max-width:100%}
.form-grid :deep(.ui-property-control>div>input[type=number]){flex:0 1 var(--ui-number-width);max-width:100%}
